<script lang="ts">
  import { onMount } from "svelte";
  import { InfrastructureService, PlatformService } from "../../bindings/github.com/blacknode/blacknode/internal/service";
  import type { ServiceGraph, DependencyHealth, MonitorView, Integration } from "../../bindings/github.com/blacknode/blacknode/internal/service/models";
  import { unpack, type Versioned } from "./operationRecords";
  import { app } from "./state.svelte";
  import PageHeader from "./PageHeader.svelte";
  import { Network } from "@lucide/svelte";
  const blank = (): ServiceGraph => ({id:'',name:'',nodes:[],edges:[]});
  let graphs = $state<Versioned<ServiceGraph>[]>([]); let graph = $state(blank()); let revision = $state(0);
  let monitors = $state<MonitorView[]>([]); let integrations = $state<Versioned<Integration>[]>([]); let integrationID = $state('');
  let health = $state<DependencyHealth[]>([]); let selectedNode = $state(''); let from = $state(''); let to = $state('');
  let editing = $state(true); let busy = $state(false); let error = $state('');
  const selectedHealth = $derived(health.find(h => h.id === selectedNode));
  const affected = $derived(health.filter(h => h.affectedBy.includes(selectedNode)));
  const point = (id: string) => { const i = graph.nodes.findIndex(n => n.id === id); return { x: 155 + (i % 3) * 290, y: 60 + Math.floor(i / 3) * 135 }; };
  const color = (id: string) => { const state = health.find(h => h.id === id)?.status; return state === 'up' ? 'var(--color-success)' : state === 'down' ? 'var(--color-danger)' : state === 'affected' || state === 'expiring' ? 'var(--color-warn)' : 'var(--color-text-3)'; };
  async function refresh() { const [g,m,i] = await Promise.all([PlatformService.ListRecords('service-graph'), InfrastructureService.Monitors(), PlatformService.ListRecords('integration')]); graphs = g.map(r => unpack<ServiceGraph>(r)); monitors = m; integrations = i.map(r => unpack<Integration>(r)).filter(i => i.kind === 'prometheus'); }
  async function action(fn: () => Promise<unknown>) { busy = true; error = ''; try { await fn(); } catch(e) { error = String(e); } finally { busy = false; } }
  async function choose(id: string) { const g = graphs.find(g => g.id === id); graph = g ? structuredClone($state.snapshot(g)) : blank(); revision = g?.revision ?? 0; health = []; selectedNode = ''; editing = !g; if (g) health = await InfrastructureService.ServiceGraphHealth(g.id); }
  async function save() { await action(async () => { const d = await InfrastructureService.SaveServiceGraph(graph,revision); await refresh(); await choose(d.id); }); }
  function removeNode(id: string) { graph.nodes = graph.nodes.filter(n => n.id !== id); graph.edges = graph.edges.filter(e => e.from !== id && e.to !== id); }
  function addEdge() { if (from && to && from !== to && !graph.edges.some(e => e.from === from && e.to === to)) graph.edges = [...graph.edges,{from,to}]; }
  onMount(() => { void action(refresh); let live = true; const timer = setInterval(async () => { const id = graph.id; if (!id || editing) return; try { const h = await InfrastructureService.ServiceGraphHealth(id); if (live && graph.id === id) health = h; } catch(e) { if (live) error = String(e); } },5000); return () => {live = false;clearInterval(timer);}; });
</script>
<div class="flex h-full min-h-0 flex-col"><PageHeader icon={Network} title="Service dependencies" subtitle="Understand what depends on a failing service" /><div class="ops-body ops-form">
  {#if error}<p class="ops-error" role="alert">{error}</p>{/if}
  <div class="ops-actions"><select aria-label="Service map" value={graph.id} onchange={e => action(() => choose(e.currentTarget.value))}><option value="">New map</option>{#each graphs as g (g.id)}<option value={g.id}>{g.name}</option>{/each}</select>{#if graph.id}<button onclick={() => editing = !editing}>{editing ? 'View map' : 'Edit map'}</button><button disabled={busy} onclick={() => action(async () => { await PlatformService.DeleteRecord('service-graph',graph.id,revision); await refresh(); await choose(''); })}>Delete map</button>{/if}<button onclick={() => app.view = 'uptime'}>Manage health checks</button></div>
  {#if editing}<div class="ops-card ops-form"><label>Map name<input bind:value={graph.name} placeholder="Production web services" /></label><div class="ops-actions"><select aria-label="Trace metrics integration" bind:value={integrationID}><option value="">Prometheus integration</option>{#each integrations as i (i.id)}<option value={i.id}>{i.name}</option>{/each}</select><button disabled={busy || !integrationID} onclick={() => action(async () => { graph = await InfrastructureService.DiscoverServiceGraph(integrationID); revision = 0; health = []; })}>Discover from traces</button></div><p class="ops-muted">Discovery reads client/server service graph metrics from Prometheus. Review the discovered map and assign health checks before saving.</p>
    {#each graph.nodes as node (node.id)}<div class="ops-grid border-b hairline pb-3"><label>Service name<input bind:value={node.name} /></label><label>Kind<select bind:value={node.kind}><option value="service">Application</option><option value="load-balancer">Load balancer</option><option value="database">Database</option><option value="cache">Cache</option><option value="queue">Queue</option><option value="external">External service</option></select></label><label>Host<select bind:value={node.hostID}><option value="">Unassigned</option>{#each app.hosts as h (h.id)}<option value={h.id}>{h.name} · {h.host}</option>{/each}</select></label><label>Health check<select bind:value={node.monitorID}><option value="">Unassigned</option>{#each monitors as m (m.monitor.id)}<option value={m.monitor.id}>{m.monitor.name}</option>{/each}</select></label><button onclick={() => removeNode(node.id)}>Remove service</button></div>{/each}
    <div><button onclick={() => graph.nodes = [...graph.nodes,{id:crypto.randomUUID(),name:'',kind:'service',hostID:'',monitorID:''}]}>Add service</button></div>
    <div class="ops-actions"><select aria-label="Dependent service" bind:value={from}><option value="">Service</option>{#each graph.nodes as n (n.id)}<option value={n.id}>{n.name}</option>{/each}</select><span>depends on</span><select aria-label="Dependency" bind:value={to}><option value="">Dependency</option>{#each graph.nodes as n (n.id)}<option value={n.id}>{n.name}</option>{/each}</select><button disabled={!from || !to || from === to} onclick={addEdge}>Add dependency</button></div>
    {#each graph.edges as edge, i}<div class="ops-actions"><span>{graph.nodes.find(n => n.id === edge.from)?.name} → {graph.nodes.find(n => n.id === edge.to)?.name}</span><button onclick={() => graph.edges = graph.edges.filter((_,j) => j !== i)}>Remove dependency</button></div>{/each}
    <button class="primary" disabled={busy || !graph.name} onclick={save}>Save map</button></div>{/if}
  {#if graph.nodes.length}<p class="ops-muted">Arrows point toward dependencies. Select a service to see its health and affected consumers.</p><div class="overflow-auto rounded border hairline"><svg viewBox={`0 0 900 ${Math.ceil(graph.nodes.length/3)*135}`} class="w-full min-w-[650px]" role="img" aria-label="Service dependency map"><defs><marker id="service-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="var(--color-text-4)" /></marker></defs>
    {#each graph.edges as edge}{@const a = point(edge.from)}{@const b = point(edge.to)}<path d={`M ${a.x} ${a.y+25} Q ${(a.x+b.x)/2} ${Math.max(a.y,b.y)+65} ${b.x} ${b.y+25}`} stroke="var(--color-text-4)" stroke-width="1.5" fill="none" marker-end="url(#service-arrow)" />{/each}
    {#each graph.nodes as n (n.id)}{@const p = point(n.id)}<g role="button" tabindex="0" aria-label={`Inspect ${n.name}`} onclick={() => selectedNode = n.id} onkeydown={e => {if(e.key === 'Enter' || e.key === ' '){e.preventDefault();selectedNode = n.id;}}}><rect x={p.x-120} y={p.y-28} width="240" height="56" rx="8" fill="var(--color-surface-2)" stroke={selectedNode === n.id ? 'var(--color-accent)' : color(n.id)} stroke-width="2"/><text x={p.x} y={p.y-2} text-anchor="middle" fill="var(--color-text-1)" font-size="12">{n.name.slice(0,30)}</text><text x={p.x} y={p.y+16} text-anchor="middle" fill={color(n.id)} font-size="11">{health.find(h => h.id === n.id)?.status ?? 'unknown'}</text></g>{/each}
  </svg></div>{/if}
  {#if selectedNode}<div class="ops-card"><h3>{graph.nodes.find(n => n.id === selectedNode)?.name}</h3><p>Status: {selectedHealth?.status ?? 'unknown'}</p><p>Failing dependencies: {selectedHealth?.affectedBy.map(id => graph.nodes.find(n => n.id === id)?.name).join(', ') || 'None detected'}</p><p>Affected consumers: {affected.map(h => graph.nodes.find(n => n.id === h.id)?.name).join(', ') || 'None detected'}</p></div>{/if}
</div></div>
